import json,pathlib
root=pathlib.Path(__file__).parent
html=(root/'index.html').read_text();js=(root/'app.js').read_text()
server='''const HTML=HTML_VALUE;const JS=JS_VALUE;
const BASE='https://testnet.vibevibe.fun/api/v1/chains/46630';
const response=(body,status=200)=>new Response(JSON.stringify(body),{status,headers:{'content-type':'application/json','cache-control':'no-store'}});
export default {async fetch(request){const url=new URL(request.url);if(request.method!=='GET')return response({error:'Read-only endpoint'},405);if(url.pathname==='/app.js')return new Response(JS,{headers:{'content-type':'text/javascript'}});if(url.pathname==='/')return new Response(HTML,{headers:{'content-type':'text/html; charset=utf-8','content-security-policy':"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; connect-src 'self'; img-src 'self'; frame-ancestors 'none'",'x-content-type-options':'nosniff','referrer-policy':'no-referrer'}});
const match=/^\\/api\\/token\\/(0x[a-fA-F0-9]{40})$/.exec(url.pathname);if(!match)return response({error:'Not found'},404);let source='',generation='V6';try{let endpoint=BASE+'/v6/launches/'+match[1];let upstream=await fetch(endpoint,{headers:{accept:'application/json'},signal:AbortSignal.timeout(15000)});if(upstream.status===404){generation='Legacy';endpoint=BASE+'/launches/'+match[1];upstream=await fetch(endpoint,{headers:{accept:'application/json'},signal:AbortSignal.timeout(15000)})}if(!upstream.ok)return response({error:upstream.status===404?'Token not found in the supported testnet sources.':'The upstream data source is unavailable ('+upstream.status+').'},upstream.status===404?404:502);const body=await upstream.json();const l=body.data?.launch;if(!l||l.tokenAddress?.toLowerCase()!==match[1].toLowerCase())return response({error:'Source returned an unsupported launch format. No values were inferred.'},502);source=endpoint;return response({launch:l,generation,freshness:body.meta?.freshness||null,source,fetchedAt:new Date().toISOString()})}catch{return response({error:'Data source timed out or could not be read. Try again later.'},502)}}};
'''
server=server.replace('HTML_VALUE',json.dumps(html)).replace('JS_VALUE',json.dumps(js));(root/'dist/server').mkdir(parents=True,exist_ok=True);(root/'dist/server/index.js').write_text(server)
